create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
create table public.offers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, network_name text, tracking_destination_url text not null, geo_countries text[] not null default '{}', status text not null default 'ACTIVE' check (status in ('ACTIVE', 'PAUSED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index offers_user_id_idx on public.offers(user_id);
create trigger offers_set_updated_at before update on public.offers for each row execute function public.set_updated_at();
alter table public.offers enable row level security;
create policy "offers_select_own" on public.offers for select using (auth.uid() = user_id);
create policy "offers_insert_own" on public.offers for insert with check (auth.uid() = user_id);
create policy "offers_update_own" on public.offers for update using (auth.uid() = user_id);
create policy "offers_delete_own" on public.offers for delete using (auth.uid() = user_id);
create table public.campaigns (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, final_destination_url text not null, mapping_key text not null unique default substr(md5(random()::text || clock_timestamp()::text), 1, 16), click_rate_multiplier int not null default 1, max_clicks int not null default 0, google_ads_mcc_id text, google_ads_customer_id text, geo_countries text[] not null default '{}', referrers text[] not null default '{}', status text not null default 'ACTIVE' check (status in ('ACTIVE', 'PAUSED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index campaigns_user_id_idx on public.campaigns(user_id);
create unique index campaigns_mapping_key_idx on public.campaigns(mapping_key);
create trigger campaigns_set_updated_at before update on public.campaigns for each row execute function public.set_updated_at();
alter table public.campaigns enable row level security;
create policy "campaigns_select_own" on public.campaigns for select using (auth.uid() = user_id);
create policy "campaigns_insert_own" on public.campaigns for insert with check (auth.uid() = user_id);
create policy "campaigns_update_own" on public.campaigns for update using (auth.uid() = user_id);
create policy "campaigns_delete_own" on public.campaigns for delete using (auth.uid() = user_id);
create table public.campaign_offers (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade, offer_id uuid not null references public.offers(id) on delete cascade, weight int not null default 100 check (weight >= 0), unique(campaign_id, offer_id));
create index campaign_offers_campaign_id_idx on public.campaign_offers(campaign_id);
create index campaign_offers_offer_id_idx on public.campaign_offers(offer_id);
alter table public.campaign_offers enable row level security;
create policy "campaign_offers_select_own" on public.campaign_offers for select using (exists (select 1 from public.campaigns c where c.id = campaign_id and c.user_id = auth.uid()));
create policy "campaign_offers_insert_own" on public.campaign_offers for insert with check (exists (select 1 from public.campaigns c where c.id = campaign_id and c.user_id = auth.uid()));
create policy "campaign_offers_update_own" on public.campaign_offers for update using (exists (select 1 from public.campaigns c where c.id = campaign_id and c.user_id = auth.uid()));
create policy "campaign_offers_delete_own" on public.campaign_offers for delete using (exists (select 1 from public.campaigns c where c.id = campaign_id and c.user_id = auth.uid()));
create table public.click_logs (id bigint generated always as identity primary key, campaign_id uuid not null references public.campaigns(id) on delete cascade, offer_id uuid references public.offers(id) on delete set null, clicked_at timestamptz not null default now(), is_main boolean not null default false, is_consumed boolean not null default false, is_google boolean not null default false, device_type text, country text, referrer text, destination_url text, user_agent text);
create index click_logs_campaign_id_clicked_at_idx on public.click_logs(campaign_id, clicked_at desc);
alter table public.click_logs enable row level security;
create policy "click_logs_select_own" on public.click_logs for select using (exists (select 1 from public.campaigns c where c.id = campaign_id and c.user_id = auth.uid()));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, campaign_id uuid references public.campaigns(id) on delete cascade, offer_id uuid references public.offers(id) on delete set null, type text not null default 'BLOCKED_OR_STUCK_AT_INTERMEDIATE', http_status int, stuck_at_url text, final_url text, consecutive_failures int not null default 0, status text not null default 'UNREAD' check (status in ('UNREAD', 'ACKED', 'RESOLVED')), created_at timestamptz not null default now());
create index notifications_user_id_idx on public.notifications(user_id);
alter table public.notifications enable row level security;
create policy "notifications_select_own" on public.notifications for select using (auth.uid() = user_id);
create policy "notifications_update_own" on public.notifications for update using (auth.uid() = user_id);
create table public.ad_copy_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, landing_page_url text not null, target_geo_countries text[] not null default '{}', status text not null default 'PENDING' check (status in ('PENDING', 'CRAWLING', 'GENERATING', 'DONE', 'FAILED')), result jsonb, error_message text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index ad_copy_tasks_user_id_idx on public.ad_copy_tasks(user_id);
create trigger ad_copy_tasks_set_updated_at before update on public.ad_copy_tasks for each row execute function public.set_updated_at();
alter table public.ad_copy_tasks enable row level security;
create policy "ad_copy_tasks_select_own" on public.ad_copy_tasks for select using (auth.uid() = user_id);
create policy "ad_copy_tasks_insert_own" on public.ad_copy_tasks for insert with check (auth.uid() = user_id);
create policy "ad_copy_tasks_update_own" on public.ad_copy_tasks for update using (auth.uid() = user_id);
create policy "ad_copy_tasks_delete_own" on public.ad_copy_tasks for delete using (auth.uid() = user_id);
create table public.integration_settings (user_id uuid primary key references auth.users(id) on delete cascade, google_ads_connected boolean not null default false, ai_provider text not null default 'claude' check (ai_provider in ('claude', 'openai')), updated_at timestamptz not null default now());
create trigger integration_settings_set_updated_at before update on public.integration_settings for each row execute function public.set_updated_at();
alter table public.integration_settings enable row level security;
create policy "integration_settings_select_own" on public.integration_settings for select using (auth.uid() = user_id);
create policy "integration_settings_insert_own" on public.integration_settings for insert with check (auth.uid() = user_id);
create policy "integration_settings_update_own" on public.integration_settings for update using (auth.uid() = user_id);
